<?php class AppointmentController extends Controller{function index(){$db=Database::db();$d=$db->query('SELECT doctors.id,users.name FROM doctors JOIN users ON users.id=doctors.user_id WHERE verification_status="approved"')->fetchAll(PDO::FETCH_ASSOC);$this->view('appointments/index',['doctors'=>$d]);}function book(){if(empty($_SESSION['user'])){header('Location: login');return;}$db=Database::db();$q=$db->prepare('INSERT INTO appointments(patient_user_id,doctor_id,hospital_id,appointment_date,start_time,end_time,consultation_type,fee,status,reason) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$_SESSION['user']['id'],$_POST['doctor_id'],$_POST['hospital_id']?:null,$_POST['date'],$_POST['start_time'],$_POST['end_time'],$_POST['type'],$_POST['fee']?:0,'booked',$_POST['reason']]);header('Location: appointments');}}